(window.SITE_LANG_DATA = window.SITE_LANG_DATA || {})["lt"] = {"ui":{"skip":"Pereiti prie turinio","back":"← Atgal į AI-gile","lang.button":"Kalba: {name}","lang.dialog":"Pasirink kalbą","lang.search":"Ieškoti kalbų","lang.none":"Nėra tokios kalbos","lang.notYet":"{name} dar neišversta","theme.aria":"Perjungti temą: šviesi, tamsi arba juoda","theme.toLight":"Perjungti į šviesią temą","theme.toDark":"Perjungti į tamsią temą","theme.toBlack":"Perjungti į juodą temą (tikra juoda, patogi OLED ekranams)","words.underline":"Pabraukti šiuos žodžius puslapyje","words.underlineHelp":"Užvesk pelę ant taškeliais pabraukto žodžio arba bakstelėk jį, kad pamatytum, ką jis reiškia.","index.title":"AI-gile: tavo dirbtinio intelekto komanda vienoje lentoje","index.description":"AI-gile yra kanban lenta dirbtinio intelekto programavimo komandoms. Jos dirba, kol tu miegi, o tau lieka vienas trumpas sąrašas: ką nuspręsti, išbandyti ir priimti.","hero.logoAlt":"AI-gile lentos piktograma","hero.h1.html":"Tavo dirbtinio intelekto komanda vienoje&nbsp;lentoje.","hero.alpha":"🐣 Uždara ankstyva alfa","hero.alphaTitle":"Dar nebaigta: ačiū, kad išbandai!","hero.lede":"Jie kuria, kol tu miegi. Pabundi ir randi vieną trumpą krūvelę: keli klausimai, keli dalykai išbandymui, vienas kitas violetinis rombas. Paspaudi, priimi ir grįžti prie kavos.","dl.windows":"Windows programa","dl.browser":"Paleisti naršyklėje","dl.messenger":"📱 Messenger tavo telefonui","dl.soon":"Netrukus","dl.notify":"🔔 Pranešk, kai atsidarys","dl.notifySmall":"Alfa ar beta","hero.secondary":"Agile, bet komandai niekada nereikia rytinės stovimosios kavos. (Susitikimus ji vis tiek rengia.)","pitch.h2":"AI-gile tiek žodžių, kiek nori","pitch.lede":"Pasirink ilgį, nuo vieno žodžio iki 144. Kiekvienas ilgis yra atskiras aprašymas, parašytas būtent tokiam dydžiui. Vilk slankiklį arba spausk rodyklių klavišus.","pitch.rangeLabel":"Ilgis žodžiais","pitch.dice":"🎲 kita versija","pitch.words.one":"{n} žodis","pitch.words.other":"{n} žodžių","pitch.letters.one":"{n} raidė","pitch.letters.other":"{n} raidžių","pitch.chars.one":"{n} simbolis","pitch.chars.other":"{n} simbolių","count.line.html.one":"Šiuo metu lentoje yra {n} kortelė","count.line.html.other":"Šiuo metu lentoje yra {n} kortelių","features.aria":"Ką ji daro","f.pile.h":"Viena krūvelė tau","f.pile.html":"<b>Tau</b> kaupia viską, kas laukia tavęs, iš visų projektų: klausimus, dalykus išbandymui, užduotis, kurias gali atlikti tik žmogus. Eilė parodo, kas toliau ir kiek tai užtruks.","f.sleep.h":"Komandos, dirbančios, kol tu miegi","f.sleep.p":"Kiekvienas projektas turi vadovą ir dirbtinio intelekto agentų komandą. Pakomentuok kortelę, ir komanda atsibunda, atlieka darbą ir grąžina jį su žingsniais, kuriuos gali atlikti ir pavargęs žmogus.","f.tester.h":"Pirmiausia tikrina dirbtinio intelekto testuotojas","f.tester.p":"Prieš tau kažką parodant, testuotojas atlieka žingsnius programos kopijoje ir parodo, ką pamatė, su ekrano nuotrauka. Peržvelk išlaikiusius ir priimk vienu paspaudimu.","f.proof.h":"Įrodymai, ne pažadai","f.proof.p":"Kiekvienas perdavimas parodo, kas pasikeitė: failus, skirtumus, ekrano nuotraukas. Nereikia atidarinėti kiekvienos programos, kad sužinotum, ar jau padaryta.","f.chat.h":"Kalbėkis su savo vadovais","f.chat.p":"Kaip Discord: juosta su viena piktograma kiekvienam projektui ir violetiniais rombais tam, kam reikia tavęs. Parašyk vadovui idėją, o jis paverčia ją kortelėmis ir planu su mygtuku ✅ Pirmyn.","f.tidy.h":"Pati susitvarko","f.tidy.p":"Susijusios kortelės sujungiamos į vieną, painūs pavadinimai sutvarkomi, o žetonų patikra palaiko kodą lengvą. Mažiau ką perjunginėti, mažiau ką galvoti.","f.private.h":"Tavo ir tavo kompiuteryje","f.private.li1":"Lenta veikia tavo paties kompiuteryje ir atsako tik tau.","f.private.li2":"Privačios žmonių žinutės šifruojamos nuo galo iki galo.","f.private.li3":"Jokių paskyrų, sekliklių ar slapukų.","f.lang.h":"Tavo kalba","f.lang.p":"Daugiau nei 120 kalbų: nuo olandų, valų ir japonų iki piratų, Yodos ir klingonų, o profesiniam žargonui galima greitai grįžti prie anglų kalbos.","f.service.h":"Nuo idėjos iki tikros paslaugos","f.service.p":"Su AI sukūrei kažką, kuo žmonės dabar naudojasi? Pažymėk tai kaip paslaugą, ir lenta padės ją gerai prižiūrėti: veikimo patikros, viešas būsenos puslapis, incidentai su aprašymu, pakeitimai, kuriems reikia Go, kasdien tikrinamos atsarginės kopijos. Pagalba išmoko kiekvieno žingsnio pakeliui.","msgr.h2":"AI-gile Messenger: tavo komanda kišenėje","msgr.p1":"Kalbėkis su savo AI komanda neatidarydamas lentos. Rašyk projektų vadovams ir draugams, peržiūrėk kortelės testavimo žingsnius ir į juos atsakyk – viskas iš telefono.","msgr.p2":"Norėdamas susieti, nuskenuok QR kodą savo lentoje. Pirmas kartas? Draugiškas demonstracinis pokalbis viską aprodys.","msgr.when":"Pirmiausia Android, po to žiniatinklio versija telefonams ir iPhone.","msgr.who":"Tavo projekto vadovas","msgr.b1":"Tamsaus režimo pataisymas paruoštas. Atsiųsti testavimo žingsnius?","msgr.b2":"Taip, prašau!","msgr.b3":"1. Atidaryk Nustatymus. 2. Pasirink Tamsų. Ar atrodo gerai?","tl.aria":"Laiko juosta nuo pirmo pokalbio iki planų","tl.h2":"Nuo pirmo pokalbio iki to, kas laukia","tl.lede":"Tikros datos ir laikas tavo laiko juostoje. Po šiandien tai tik planas, be pažadėtų datų.","tl.today":"Šiandien","tl.planned":"planuojama","tl.cards.one":"{n} kortelė","tl.cards.other":"{n} kortelių","join.h2":"Prisijunk","join.lede":"AI-gile kuria barzdotas keistuolis su AuDHD ir keliomis kovomis dėl psichikos sveikatos, ir daugybė kantrių agentų. Kol kas ji uždara: tik uždara alfa su draugais. Nori išbandyti, kai atsivers?","join.btn":"Užsiregistruoti","join.small":"Parašysime el. paštu, ir nieko daugiau","footer.tag":"AI-gile. Jokių sekliklių, jokių slapukų, jokios stovimosios kavos.","footer.licence":"Verslo licencija","footer.status":"Būsena","footer.privacy":"Ką saugome","footer.thanks":"Skambučiai – ChilledChat dėka","form.sending":"Siunčiama…","form.failed":"Nepavyko: pabandyk vėliau.","form.offline":"Nepavyko pasiekti AI-gile: pabandyk vėliau.","form.keep":"Tai naudojame tik tam, kad tau atsakytume, o paskui ištriname. Jokių sekliklių, jokių slapukų.","form.keepLink":"Ką saugome","interest.title":"AI-gile: pranešk man, kai atsidarys alfa","interest.description":"Palik el. paštą, ir sužinosi, kada atsidarys uždara AI-gile alfa ar beta.","interest.h1":"🔔 Pranešk, kai atsidarys","interest.lede":"AI-gile yra uždaroje ankstyvoje alfoje. Palik el. paštą ir parašysime vieną kartą, kai atsiras vieta tau.","interest.email":"Tavo el. paštas","interest.which":"Kuris testas?","interest.alpha":"Uždara alfa: ankstyva, šiurkšti, daug pokyčių","interest.beta":"Beta: stabilesnė, vėliau","interest.both":"Bet kuri, kuri bus pirma","interest.submit":"Įrašykite mane į sąrašą","interest.thanks":"Ačiū! Esi sąraše.","licence.title":"AI-gile: verslo licencija","licence.description":"Naudoji AI-gile savo versle? Paprašyk nemokamos verslo licencijos.","licence.h1":"📜 Verslo licencija","licence.lede":"Naudoji AI-gile darbe? Papasakok, kas esi ir ką veiki. Jei tai daro gero, licencija nemokama.","licence.company":"Įmonė","licence.website":"Svetainė","licence.what":"Ką veiki","licence.how":"Kuo tai padeda pasauliui","licence.email":"El. paštas","licence.submit":"Pateikti","licence.thanks":"Ačiū! Atsakysime el. paštu.","status.title":"AI-gile būsena","status.h1":"AI-gile būsena","status.quiet":"Viskas ramu","status.intro":"Ar AI-gile šiuo metu veikia? Šis puslapis kas 5 minutes tikrina svetainę, lentų bendrinimą, skambučius ir atsisiuntimą.","status.up":"Veikia (atsakė per {ms} ms)","status.slow":"Neatsakė į paskutinį patikrinimą, bandoma iš naujo","status.down":"Neveikia: neatsakė į du paskutinius patikrinimus","status.svc.web":"Svetainė","status.svc.web.offers":"Ši svetainė: kas yra AI-gile, ir susidomėjimo forma","status.svc.boards":"Lentų bendrinimas","status.svc.boards.offers":"Viešos lentos, žinutės tarp draugų ir kvietimai","status.svc.calls":"Skambučiai","status.svc.calls.offers":"Balsas, vaizdas ir ekrano bendrinimas AI-gile","status.svc.download":"Atsisiuntimas","status.svc.download.offers":"„Windows“ diegimo programa ir kvietimų nuorodos","status.checking":"Tikrinama…","status.offline":"Šiuo metu nepavyksta pasiekti būsenos tarnybos (bandoma iš naujo)","status.updated":"atnaujinta {ago}","status.justNow":"ką tik","status.min":"prieš {n} min.","status.hours":"prieš {n} val.","status.days":"prieš {n} d.","privacy.title":"AI-gile: ką saugome","privacy.h1":"Ką saugome","privacy.lede":"Trumpai: tik tai, ką mums atsiunti, ir neilgai.","privacy.only":"Tik tai, ką mums atsiunti: tai, ką įrašai į formą, pavyzdžiui, savo el. paštą. Nieko kito apie tave.","privacy.sealed":"Tai užantspauduojama, kad mūsų serveris negalėtų to perskaityti: tavo naršyklėje, dar prieš išsiunčiant (senesnėje naršyklėje – vos atkeliavus). Atidaryti tai gali tik mūsų pačių lenta.","privacy.server":"Iš serverio tai ištrinama, vos tik pasiekia mūsų lentą. Visa, kas ten dar lieka po 30 dienų, vis tiek ištrinama.","privacy.board":"Savo lentoje tai laikome tik tol, kol tau atsakome, o tada ištriname ir iš ten.","privacy.none":"Jokių sekliklių, jokių slapukų, jokios analitikos.","privacy.local":"Tavo kalba ir šviesaus ar tamsaus režimo pasirinkimas lieka tavo paties naršyklėje. Jie mums niekada nesiunčiami.","privacy.ask":"Nori, kad būtų ištrinta anksčiau? Atsakyk į mūsų laišką ir pasakyk.","live.h2":"Stebėkite, kaip tai kuriama, tiesiogiai","live.caption":"Kiekviena kortelė paslėpta: matote darbo formą, o ne žodžius.","live.watching.one":"tiesiogiai: {n} stebi","live.watching.other":"tiesiogiai: {n} stebi","live.last.now":"Paskutinė kortelė perkelta ką tik","live.last.min.one":"Paskutinė kortelė perkelta prieš {n} min.","live.last.min.other":"Paskutinė kortelė perkelta prieš {n} min.","live.last.hour.one":"Paskutinė kortelė perkelta prieš {n} val.","live.last.hour.other":"Paskutinė kortelė perkelta prieš {n} val.","live.last.day.one":"Paskutinė kortelė perkelta prieš {n} d.","live.last.day.other":"Paskutinė kortelė perkelta prieš {n} d.","live.offline":"Tiesioginė lenta trumpam ilsisi. Užsukite netrukus.","live.cols":"Backlog|Reikia padaryti|Vykdoma|Komanda tikrina|Tau išbandyti|Komandai|Atlikta","pitch.words.few":"{n} žodžiai","pitch.letters.few":"{n} raidės","pitch.chars.few":"{n} simboliai","count.line.html.few":"Šiuo metu lentoje yra {n} kortelės","tl.cards.few":"{n} kortelės"},"lines":{"unit":"words","sizes":[{"n":1,"texts":["Kanban.","Robotai.","Deleguota."]},{"n":2,"texts":["Robotų kanban.","Agentai tvarkomi.","Idėjos įgyvendintos."]},{"n":3,"texts":["Kanban robotams.","Idėjos tampa funkcijomis.","Nemokamas agentų kanban."]},{"n":5,"texts":["Kanban lenta, kurią vairuoja agentai.","Tu rašai korteles. Agentai kuria.","Nemokama, vietinė, išbandyta, kiek kvailoka."]},{"n":8,"texts":["Nemokama kanban lenta, kurioje dirba dirbtinio intelekto agentai.","Užrašai idėją. Agentai ją sukuria. Tu ją priimi.","Agile vienam žmogui ir daugybei labai kantrių robotų."]},{"n":13,"texts":["Kanban lenta tavo kompiuteryje, kurioje kortelių imasi dirbtinio intelekto agentai, o tu čia vyresnysis.","Parašyk idėją. Agentų komanda ją sukuria. Testuotojas patikrina. Tau lieka tik pasakyti taip.","Jokių paskyrų, jokių sekliklių: lenta, keli robotai ir tu, kuris čia viską sprendi."]},{"n":21,"texts":["AI-gile yra kanban lenta darbui su dirbtinio intelekto programavimo agentais. Jie ima korteles, o tu jas išbandai ir priimi.","Kiekvienas projektas turi vadovą ir dirbtinio intelekto agentų komandą. Pakomentuok bet kurią kortelę, ir komanda ima dirbti.","Nemokama asmeninė užduočių lenta, veikianti tavo paties kompiuteryje, be paskyrų. Darbininkai yra robotai. Tas, kuris sako taip, esi tu."]},{"n":34,"texts":["Dedi idėjas į lentą. Dirbtinio intelekto agentų komanda paverčia jas veikiančiomis funkcijomis, išbando ir grąžina su žingsniais, kaip pačiam pabandyti. Niekas nelaikoma padaryta, kol to nepasakai tu.","AI-gile yra namie pagaminta kanban lenta, kurią Richas sukūrė su didele pagalba agentų, kuriuos ji dabar valdo. Ji nemokama, veikia tavo kompiuteryje ir dalijamasi su draugais, o ne parduodama.","Įsivaizduok įprastą kanban lentą su stulpeliais nuo Backlog iki Done, tik kortelių čia imasi dirbtinio intelekto agentai. Jie praneša apie pažangą, užstrigę klausia ir visada laukia tavo nykščio aukštyn."]},{"n":55,"texts":["AI-gile yra kanban lenta, kurioje komandą sudaro dirbtinio intelekto agentai. Kiekvienas projektas turi vadovą, kuris planuoja darbą, ir pagalbininkus, kurie jį atlieka. Kai funkcija paruošta, dirbtinio intelekto testuotojas ją išbando ir padaro ekrano nuotrauką, o tada ji patenka į tavo krūvelę. Priimk ją arba pakomentuok, ir ją perdarys.","Viskas prasidėjo nuo vieno žmogaus noro sekti daugybę dirbtinio intelekto programavimo seansų vienu metu, o išaugo į tikrą lentą. Ji veikia tavo kompiuteryje, nereikalauja paskyros ir neturi sekliklių. Ji nemokama draugams ir smalsuoliams. Ji dar nebaigta, tad tikėkis šiurkštumų ir kartais netikėtumų. Dirbame ją kasdien, po truputį, kartu su draugais, kurie ją bando.","Štai sąžininga versija. Idėjas vis tiek turi sugalvoti pats ir rezultatus vis tiek turi patikrinti pats. AI-gile padaro viską, kas tarp to: laiko korteles tvarkingai, pažadina reikiamą agentą, kai pakomentuoji, parodo, kas tiksliai pasikeitė, ir surenka viską į vieną trumpą krūvelę tau. Tau lieka smagiausia dalis: sugalvoti ir nuspręsti."]},{"n":89,"texts":["AI-gile yra nemokama kanban lenta, kurią paleidi savo kompiuteryje. Vietoj žmonių kiekvienas projektas turi dirbtinio intelekto agentų komandą: vadovą, kuris tavo idėjas paverčia kortelėmis ir planu, ir pagalbininkus, kurie kortelių imasi pagal svarbą. Kai kas nors sukurta, dirbtinio intelekto testuotojas atlieka bandymo žingsnius ir parodo, ką pamatė. Tada viskas laukia vienoje krūvelėje, pavadintoje Tau. Priimi arba pakomentuoji, ir komanda bando dar kartą. Niekas nepasiekia Done be tavęs. Visa tai vyksta tavo kompiuteryje, be paskyrų ir be jokio sekimo.","Kelios funkcijos, kurių galbūt nesitikėjai. Naktinė sargyba papildo stulpelį Ko reikia padaryti, kol tu miegi, rinkdamasi korteles, kurioms nereikia tavo atsakymo. Žetonų skaitiklis rodo, kiek agentai šiandien ir šią savaitę sunaudojo, o No Token Mode liepia jiems nustoti eikvoti. Gali rašyti draugams, o privačios žinutės šifruojamos nuo galo iki galo. Lenta kalba maždaug 120 kalbų, tarp jų olandų, flamandų, piratų ir klingonų. Nė už vieną nereikia mokėti, ir niekas čia tau nieko nebando parduoti. Viskas veikia vietoje, tavo kompiuteryje.","AI-gile yra mažas asmeninis projektas, o ne įmonė. Richas norėjo prižiūrėti kelis dirbtinio intelekto programavimo projektus neatidarinėdamas kiekvienos programos, tad jis su agentais sukūrė tam lentą, o paskui ja pačia sukūrė likusią savęs dalį. Ji yra uždaroje ankstyvoje alfoje, vadinasi, veikia, daugmaž, saujelei draugų. Nėra nei kainų puslapio, nei naujienlaiškio, nei augimo plano. Jei skamba naudinga, gali paprašyti išbandyti, kai ji kiek atsivers. Jokio spaudimo, tik lenta, kuri pamažu tampa geresnė."]},{"n":144,"texts":["AI-gile yra kanban lenta vienam žmogui ir daugybei dirbtinio intelekto agentų. Ji veikia tavo paties kompiuteryje ir yra visiškai nemokama. Pridedi projektus, ir kiekvienas gauna vadovą bei nedidelę komandą. Su vadovu kalbiesi kaip per Discord ir aprašai idėją, o jis paverčia ją kortelėmis ir planu, tada laukia, kol paspausi Pirmyn. Komanda eina per korteles pagal svarbą, naudodama paprastą komandų eilutę, sukurtą kalbos modeliams. Prieš tau ką nors grąžinant, dirbtinio intelekto testuotojas atlieka žingsnius programos kopijoje ir prideda ekrano nuotrauką. Baigtas darbas patenka į tavo krūvelę kartu su pakeistais failais ir skirtumais. Priimi jį arba paliki komentarą, ir komanda pabunda bei bando iš naujo. Kortelę į Done gali perkelti tik tu. Visa tai vyksta tavo kompiuteryje, be paskyrų, be sekliklių ir be slapukų. Ji kalba maždaug 120 kalbų, o draugai gali rašyti vieni kitiems privačiai ir užšifruotai. Ji dar nebaigta, uždara ankstyva alfa, bet jau dabar naudojasi pati savimi.","Maždaug toks AI-gile diena. Vakare palieki kelis komentarus: šis mygtukas ne toje vietoje, tą sąrašą reikia surikiuoti, gal galėtume turėti tamsią temą. Eini miegoti. Agentai perskaito komentarus, padaro pakeitimus, išbando ir grąžina tau. Jei stulpelis Ko reikia padaryti ištuštėja, naktinė sargyba papildo jį iš atsargų kortelėmis, kurioms tavo atsakymo nereikia. Ryte lieka viena trumpa krūvelė: pora klausimų ir keli dalykai išbandymui, kiekvienas su žingsniais, kuriuos gali atlikti ir mieguistas žmogus, bei ekrano nuotrauka, kad veikia. Perbėgi, priimi tinkamus ir grąžini likusius. Žetonų skaitiklis parodo, kiek viskas sunaudojo, o No Token Mode skirtas taupioms savaitėms. Tada pusryčiauji, kuriuose agentai kol kas padėti negali. Naktį lenta dirba už tave, o dieną sprendimus visada priimi tu. Jei kas nors nepavyko, tiesiog parašai komentarą, ir komanda pabunda iš naujo. Taip diena po dienos tavo idėjos keliauja iš minčių į veikiančią programą, o tu nepraleidi vakaro prie kodo.","Pirmiausia, kas AI-gile nėra. Tai ne startuolis, ji neparduodama ir niekas nerenka tavo duomenų. Tai nemokama lenta, veikianti tavo kompiuteryje, be paskyrų, sekliklių ir slapukų. O kas ji yra: viena tvarkinga vieta matyti visus dirbtinio intelekto programavimo projektus iš karto, kur agentų komanda atlieka korteles, o sprendimus priimi tu. Ji sujungia susijusias korteles, sutvarko painius pavadinimus ir stebi, kad kodas liktų lengvas. Ji kalba maždaug 120 kalbų, nuo olandų ir flamandų iki piratų ir klingonų. Draugai gali rašyti vieni kitiems, privačiai ir užšifruotai. Ją sukūrė Richas ir daugybė kantrių agentų, daugiausia naudodamiesi ja pačia. Ji yra uždaroje ankstyvoje alfoje, todėl kai kur šiurkšti. Jei skamba smagiai, paprašyk mandagiai, ir gal pateksi anksti. Mums patinka, kad ji lėta, kantri ir sąžininga: nieko neparduoda, nieko neslepia, tik tvarkingai laiko visus tavo projektus vienoje vietoje."]}],"quips":{"1":"Vienas žodis. Drąsu. Gal net per drąsu.","3":"Trys žodžiai. Jau sąžiningiau nei dauguma produktų puslapių.","8":"Aštuoni žodžiai. Vis tiek trumpiau nei stovimasis susitikimas.","21":"Beje, ilgiai yra istorijos taškai. Žinoma, kad taip.","55":"Penkiasdešimt penki žodžiai. Kol skaitei, baigtos dvi kortelės.","144":"Tai ilgiausia versija. 233 nėra. Agentai nuėjo miegoti."}},"timeline":{"first-idea.name":"Pirmoji idėja","first-idea.line":"Pats pirmas pokalbis, dar nesant nė eilutės kodo.","first-board.name":"Pirmoji lenta","first-board.line":"Lenta, sekanti savo paties kūrimą: kortelės, stulpeliai, tempimas, projektai.","team-roles.name":"Komanda ir vaidmenys","team-roles.line":"Agentų profiliai, komandų šablonai, erdvės ir kas ką daro.","install.name":"Diegimas ir leidimai","install.line":"Zip, kurį gali įsidiegti draugas, savaiminiai atnaujinimai, kanalai ir grąžinimas atgal.","usage-saver.name":"Sąnaudų taupymas","usage-saver.line":"Matuoja, kiek kainuoja paleidimai, laiko kodą lengvą ir taupo tavo limitą.","friends.name":"Draugai ir dalijimasis","friends.line":"Privačios žinutės, užšifruotas relay, kvietimai, vaidmenys ir bendri projektai.","languages.name":"Kalbos","languages.line":"Kiekvienas ekrano tekstas kalbos faile, pirmiausia olandų ir flamandų.","ai-tester.name":"Dirbtinio intelekto testuotojas","ai-tester.line":"Testuotojas pirmas patikrina kiekvieną perdavimą ir parodo, ką pamatė.","website.name":"Svetainė","website.line":"aigile.lol, pristatomasis puslapis ir ši laiko juosta.","streaming.name":"Pokalbiai ir transliacijos","streaming.line":"Discord, Twitch, OBS, transliuotojo režimas, GIF ir jaustukai.","no-ai.name":"Leidimas be dirbtinio intelekto","no-ai.line":"Lenta tiems, kurie programuoja be dirbtinio intelekto, ir vieši projektai.","night-watch.name":"Naktinė sargyba","night-watch.line":"Sargas ir Scrum Master palaiko komandų darbą, kol tu miegi.","p-more.name":"Visa kita","p-more.line":"Mažesnės idėjos, vis dar laukiančios savo eilės.","p-android.name":"Telefonas ir Android","p-android.line":"Pasiek savo lentą iš telefono, vėliau ir iš savos Android programos.","p-release.name":"Alfa ir toliau","p-release.line":"Uždara alfa, gyva svetainė, tada beta.","p-languages.name":"Daugiau kalbų","p-languages.line":"Daugiau nei šimtas kalbų ir panardinimo režimas besimokantiems.","p-engines.name":"Daugiau dirbtinio intelekto variklių","p-engines.line":"Kiekvienam agentui pasirink Claude, Codex ar Gemini.","p-pro.name":"Profesionali praktika","p-pro.line":"Rizikos žymos, sujungimo vartai, incidentų kortelės ir apsauginiai turėklai.","p-self.name":"Rūpinimasis tavimi","p-self.line":"Pavargimo režimas, priminimai pasirūpinti savimi ir 4:20.","p-servers.name":"Serveriai ir augimas","p-servers.line":"Bendri serverio nustatymai, vaidmenys ir augimo planavimas.","p-livestream.name":"Transliacijų priedai","p-livestream.line":"Twitch pokalbis, savi jaustukai ir vieša gyva peržiūra."},"words":{"button":"📖 Profesinis žargonas","h":"📖 Žodžiai paaiškinti","intro":"Žodžiai, kuriuos sutiksi AI-gile, paprasta kalba: kaip kurti, kaip saugiai keisti, kaip išlaikyti veikiantį naudotojams ir kaip dirbti komandoje su AI.","search":"Ieškoti žodžio…","none":"Atitinkančių žodžių nėra.","close":"Uždaryti","count":{"one":"{count} žodis","other":"Žodžių: {count}"},"groups":[{"id":"build","name":"🛠️ Kūrimas"},{"id":"change","name":"🔀 Saugus keitimas"},{"id":"run","name":"🛎️ Paslaugos priežiūra"},{"id":"team","name":"🤝 Darbas komandoje (ir su AI)"}],"list":[{"id":"repo","g":"build","word":"Repo","text":"Projekto kodo aplankas su visa commit'ų istorija, paprastai laikomas ir GitHub'e.","also":["repository","saugykla"]},{"id":"branch","g":"build","word":"Branch","text":"Atskira darbo kodo šaka, kad pakeitimus būtų galima daryti neliečiant pagrindinės versijos.","also":["branches","šaka","šakos"]},{"id":"commit","g":"build","word":"Commit","text":"Išsaugota kodo momentinė kopija su trumpa pastaba, kas pasikeitė. Prie bet kurios visada gali grįžti.","also":["commits","commit'ai","komitas"]},{"id":"push","g":"build","word":"Push","text":"Išsaugotų momentinių kopijų (commit'ų) siuntimas iš šio kompiuterio į GitHub, kad jos būtų saugiai išsaugotos ir prieinamos kitiems."},{"id":"merge","g":"build","word":"Merge","text":"Šakos pakeitimų sujungimas atgal į pagrindinę versiją."},{"id":"pr","g":"build","word":"Pull request","text":"Prašymas patikrinti šakos pakeitimus ir sujungti juos į pagrindinę versiją.","also":["PR"]},{"id":"refactor","g":"build","word":"Refactor","text":"Kodo sutvarkymas nekeičiant, ką jis daro: mažesni failai, aiškesni pavadinimai, mažiau pasikartojimų."},{"id":"bug","g":"build","word":"Klaida","text":"Kažkas, kas neveikia taip, kaip turėtų.","also":["bug","bugs","bugai","klaidos"]},{"id":"test","g":"build","word":"Testas","text":"Baigto darbo išbandymas, kad patikrintum, ar jis daro tai, ko prašyta, prieš jį priimant.","also":["test","tests","testai"],"noTip":1},{"id":"qa","g":"build","word":"QA","text":"Angliško quality assurance, t. y. kokybės užtikrinimo, santrumpa: automatinės patikros, kurios vyksta prieš ką nors paleidžiant gyvai. Kai QA raudonas, kažkas nepavyko, ir nieko negalima paleisti gyvai, kol tai nesutaisyta.","also":["kokybės patikra","kokybės užtikrinimas"]},{"id":"deploy","g":"change","word":"Deploy","text":"Naujos versijos paleidimas į gyvą aplinką, pavyzdžiui, serveryje, kuriuo žmonės naudojasi."},{"id":"release","g":"change","word":"Leidimas","text":"Pavadintas baigto darbo paketas, kuris paleidžiamas gyvai kartu, su trumpomis pastabomis, kas pasikeitė. 🚀 Leidimai pastabas parašo iš atliktų kortelių.","also":["leidimai","release"]},{"id":"rollback","g":"change","word":"Atsukti atgal","text":"Grįžimas prie paskutinės veikusios versijos, kai nauja sukelia bėdų. AI-gile iš atšaukimo žingsnių, užrašytų ant kiekvieno pakeitimo, sudaromas kontrolinis sąrašas.","also":["rollback","atsukimas atgal","atšaukimas"]},{"id":"live","g":"change","word":"Gyvai","text":"Tikroji versija, kuria žmonės naudojasi, o ne kopija bandymams. Programuotojai ją dar vadina produkcija (production).","also":["gyva aplinka","produkcija","production"],"noTip":1},{"id":"change","g":"change","word":"Pakeitimas","text":"Suplanuotas pakeitimas to, kuo žmonės pasikliauja, iš anksto užrašytas: kas, kodėl, rizika, kada ir kaip jį atšaukti. Pradėk mygtuku 🔀 Pateikti pakeitimą.","also":["pakeitimai","pakeitimo užklausa"],"noTip":1},{"id":"risk","g":"change","word":"Rizika","text":"Kažkas, kas gali nepavykti, įvertinta pagal tai, kiek tai tikėtina ir kiek blogai būtų. ⚠️ Rizikos laiko jas viename sąraše, nuo didžiausio balo, kiekviena su data, kada pažiūrėti dar kartą.","also":["rizikos","rizikų registras"]},{"id":"chgwin","g":"change","word":"Pakeitimų langas","text":"Laikas, kai pakeitimus galima paleisti gyvai, pavyzdžiui, ramus antradienio vakaras. Už lango ribų pakeitimo kortelės užbaigti negalima, nebent tai skubus atvejis.","also":["pakeitimų langai","change window"]},{"id":"gonogo","g":"change","word":"Go / no go","text":"Greitas balsavimas prieš pat paleidžiant pakeitimą gyvai: kiekvienas, kuris turi patvirtinti, sako Go arba No go. Pakeitimas vykdomas tik tada, kai visi sutinka.","also":["go/no go","go-no-go"]},{"id":"approval","g":"change","word":"Patvirtinimas","text":"„Taip“ laukimas prieš pradedant darbą. Draugo pateikta kortelė arba pakeitimas laukia skiltyje ✅ Patvirtinimai, kol tu jį patvirtinsi arba atmesi.","also":["patvirtinimai"]},{"id":"quiettime","g":"change","word":"Ramybės laikas","text":"Laikotarpis, pavyzdžiui, transliacija, demonstracija ar naktis, kai nieko nepaleidžiama gyvai. Komandos toliau dirba ir testuoja, bet paleidimas gyvai laukia, kol jis baigsis. Kitur tai vadinama pakeitimų įšaldymu (change freeze).","also":["ramybės laikai","pakeitimų įšaldymas","change freeze"]},{"id":"service","g":"run","word":"Paslauga","text":"Kažkas, ką sukūrei ir kuo žmonės pasikliauja, pavyzdžiui, svetainė ar programėlė, prižiūrima, kad ir toliau veiktų. Pažymėk „Šis projektas yra paslauga“ ir nurodyk, ką ji siūlo, kas ja naudojasi ir kas budi.","also":["paslaugos","service"]},{"id":"uptime","g":"run","word":"Veikimo patikra","text":"Automatinė patikra kas kelias minutes, ar tavo paslauga vis dar atsako. Jei ji kelis kartus iš eilės nepavyksta, AI-gile pati atidaro incidento kortelę.","also":["uptime","veikimo laikas"]},{"id":"statuspage","g":"run","word":"Būsenos puslapis","text":"Viešas puslapis, rodantis, ar paslauga veikia (žalia, oranžinė ar raudona), su naujausia žinute, kad naudotojai galėtų pasitikrinti patys, užuot klausę.","also":["būsenos puslapiai","status page"]},{"id":"incident","g":"run","word":"Incidentas","text":"Kažkas, kas dabar sugedę tiems, kurie tuo naudojasi, pavyzdžiui, neveikia svetainė. 🔥 Incidento kortelė aplenkia eilę: svarbiausia vėl viską paleisti.","also":["incidentai"]},{"id":"major","g":"run","word":"Didelis incidentas","text":"Didelis incidentas: paveikta daug žmonių arba gresia pavojus pinigams ar duomenims. Vienas mygtukas visas komandas nukreipia į jį (spiečius), pažadina budintįjį ir kas 30 minučių prašo būsenos naujienos.","also":["dideli incidentai","major incident"]},{"id":"oncall","g":"run","word":"Budėjimas","text":"Būti tuo, kuris atsiliepia, kai kas nors sugenda, net naktį. Kiekviena paslauga turi budintį komandos narį, kuris pirmas pažadinamas dėl jos incidentų.","also":["budintis","on call","on-call"]},{"id":"replyby","g":"run","word":"Atsakymo terminas","text":"Kiek ilgai kortelė gali laukti pirmojo atsakymo, pavyzdžiui, valandą incidentui. Po to ji gauna raudoną laikrodį, kad niekas nebūtų tyliai pamirštas. Dar vadinama atsakymo tikslu.","also":["atsakymo terminai","atsakymo tikslas","response target"]},{"id":"postmortem","g":"run","word":"Incidento analizė","text":"Trumpas žvilgsnis atgal po incidento: kas nutiko, kas padėjo ir ką pakeisti, nieko nekaltinant. Be jos incidento uždaryti negalima. Angliškai tai vadinama post-mortem.","also":["post-mortem","postmortem","poincidentinė analizė"]},{"id":"problem","g":"run","word":"Problema","text":"Paslėpta vieno ar kelių incidentų priežastis. 🧩 Problemos kortelė sugrupuoja vis pasikartojančius incidentus, kad priežastis būtų rasta ir sutaisyta visam laikui.","also":["problemos"],"noTip":1},{"id":"rootcause","g":"run","word":"Pagrindinė priežastis","text":"Tikroji priežastis, kodėl kažkas sugedo, o ne tik tai, ką matei negerai veikiant. Sutaisyk pagrindinę priežastį, ir incidentas nebesikartos.","also":["pagrindinės priežastys","šakninė priežastis","root cause"]},{"id":"workaround","g":"run","word":"Laikinas sprendimas","text":"Būdas išlaikyti viską veikiantį, kol tikras pataisymas bus paruoštas, pavyzdžiui, ką nors paleisti iš naujo, kai užstringa. Jis užrašomas ant problemos kortelės, kad niekam nereikėtų to vėl išsiaiškinti.","also":["laikini sprendimai","workaround"]},{"id":"knownerror","g":"run","word":"Žinoma klaida","text":"Problema, kurios priežastis suprasta ir kuriai yra laikinas sprendimas, bet kuri dar nesutaisyta. 🧩 Žinomos klaidos jas išvardija, kad visi naudotų laikiną sprendimą, užuot vėl knisęsi.","also":["žinomos klaidos","known error"]},{"id":"runbook","g":"run","word":"Runbook","text":"Žingsnis po žingsnio instrukcija, kaip sutaisyti žinomos rūšies bėdą, kad kiekvieną kartą būtų daroma taip pat ir greitai. Po didelio incidento komanda gali pasiūlyti tokią, o tu duosi savo OK.","also":["runbook","veiksmų instrukcija"]},{"id":"backup","g":"run","word":"Atsarginė kopija","text":"Išsaugota ankstesnė tavo duomenų kopija, kuria galima pasinaudoti, jei kas nors dingsta ar sugadinama. AI-gile kasdien daro tavo lentų atsarginę kopiją.","also":["atsarginės kopijos","backup"]},{"id":"restore","g":"run","word":"Atkūrimas","text":"Duomenų sugrąžinimas iš atsarginės kopijos. Atsarginė kopija iš tikrųjų vertinga tik tada, kai žinai, kad ją galima atkurti, todėl verta kartais pabandyti.","also":["atkurti","atkurta","restore"]},{"id":"backlog","g":"team","word":"Backlog","text":"Idėjos ir darbai, kurie dar nesuplanuoti. Niekas iš to nedaroma, kol nepersikelia į Reikia padaryti."},{"id":"sprint","g":"team","word":"Sprintas","text":"Trumpas darbo laikotarpis (dažnai savaitė ar dvi) su sutartu kortelių rinkiniu, kurį reikia baigti.","also":["sprints","sprint","sprintai"]},{"id":"standup","g":"team","word":"Stand-up","text":"Greita apžvalga: ką kiekvienas padarė, ką daro toliau ir kas trukdo.","also":["standup","stand-ups","stand-up'ai"]},{"id":"kanban","g":"team","word":"Kanban","text":"Lenta su stulpeliais (Reikia padaryti, Vykdoma, Atlikta), kurioje kortelės dirbant juda iš kairės į dešinę."},{"id":"wip","g":"team","word":"WIP riba","text":"Vykdomas darbas: daugiausia kortelių, kiek gali turėti stulpelis, kad komanda baigtų darbus, prieš pradėdama naujus.","also":["WIP","vykdomo darbo riba"]},{"id":"dod","g":"team","word":"Definition of Done","text":"Trumpas komandos kontrolinis sąrašas, ką reiškia „baigta“, pavyzdžiui, išbandyta ir paaiškinta, prieš perduodant kortelę tau. Jo dvynys, Definition of Ready, nurodo, kada kortelė pakankamai aiški, kad būtų galima pradėti.","also":["Definition of Ready","atlikimo apibrėžimas"]},{"id":"testpile","g":"team","word":"Testų krūva","text":"Baigtos kortelės, laukiančios, kol tu jas išbandysi, viena po kitos. Priimk vieną arba grąžink su pastaba, ir pasirodys kita.","also":["testų krūvos","test pile"]},{"id":"retro","g":"team","word":"Retro","text":"Žvilgsnis atgal į tai, kaip komanda dirba, kad būtų sutarta dėl vieno dalyko, kurį daryti geriau. AI-gile retro pasiūlo pakeitimą komandos darbo būdams, o tu sakai Go arba Dar ne.","also":["retrospektyva","retrospektyvos"]},{"id":"peerreview","g":"team","word":"Kolegų peržiūra","text":"Antra akių pora: kitas AI patikrina kiekvienos kortelės darbą, kol jis nepasiekė tavęs, todėl prasprūsta mažiau klaidų.","also":["kodo peržiūra","code review","peer review"]},{"id":"swarm","g":"team","word":"Spiečius","text":"Visi į darbą: kiekviena komanda atideda kitus darbus ir padeda vienam skubiam projektui, kol jis sutvarkomas. Kiti projektai tuo metu laukia.","also":["swarm","swarming"]},{"id":"scrummaster","g":"team","word":"Scrum Master","text":"Tas, kuris palaiko darbo tėkmę: pastebi užstrigusias korteles, paragina komandas ir primena tau, kas laukia. AI-gile tai visuose projektuose daro Lead Scrum Master.","also":["Lead Scrum Master","skramo meistras"]},{"id":"agent","g":"team","word":"Agent","text":"AI, kuris savarankiškai dirba su užduotimi: skaito kodą, daro pakeitimus, vykdo patikras ir praneša.","also":["agents","agentas","agentai"]},{"id":"token","g":"team","word":"Token","text":"Vienetas, kuriuo skaičiuojamas AI naudojimas: maždaug kelios perskaityto ar parašyto teksto raidės. Mažiau žetonų – daugiau plano lieka.","also":["tokens","žetonas","žetonai"]},{"id":"hook","g":"team","word":"Hook","text":"Mažas veiksmas, kuris pats įsijungia tam tikru momentu, pvz., kai prasideda AI sesija, kad komanda išgirstų tavo komentarus.","also":["hooks","kabliukas","kabliukai"]}]}};
